-- > Services
local HttpService = game:GetService('HttpService')

-- > Connections
local Original; Original = hookmetamethod(game, '__namecall', newcclosure(function(self, ...)
	local Args = {...}
	if getnamecallmethod() == 'Shutdown' then
		return print(':Shutdown()')
	end
	--
	return Original(self, table.unpack(Args))
end))

local Original; Original = hookfunction(request, function(...)
    local Args = {...}
    if Args[1].Url:find('api.platoboost.app') or Args[1].Url:find('api.platoboost.net') then
        if Args[1].Url:find('/public/whitelist/') then
            if Args[1].Url:find('&nonce=') then
                return {
                    StatusMessage = 'OK',
                    StatusCode = 200,
                    Success = true,
                    --
                    Body = HttpService:JSONEncode({
                        success = true,
                        --
                        data = {
                            valid = true,
                            hash = crypt.hash('true' .. '-' .. Args[1].Url:match('&nonce=([^&]*)') .. '-' .. '39441a8e-e185-49a3-a494-6771f350a16a', 'sha256')
                        },
                    })
                }
            elseif not Args[1].Url:find('&nonce=') then
                return {
                    StatusMessage = 'OK',
                    StatusCode = 200,
                    Success = true,
                    --
                    Body = HttpService:JSONEncode({
                        success = true,
                        --
                        data = {
                            valid = true,
                        },
                    })
                }
            end
        elseif Args[1].Url:find('/public/redeem') then
            local Body = HttpService:JSONDecode(Args[1].Body) or {}
            --
            if Body.nonce then
                return {
                    StatusMessage = 'OK',
                    StatusCode = 200,
                    Success = true,
                    --
                    Body = HttpService:JSONEncode({
                        success = true,
                        --
                        data = {
                            valid = true,
                            hash = crypt.hash('true' .. '-' .. Body.nonce .. '-' .. '39441a8e-e185-49a3-a494-6771f350a16a', 'sha256')
                        },
                    })
                }
            elseif not Body.nonce then
                return {
                    StatusMessage = 'OK',
                    StatusCode = 200,
                    Success = true,
                    --
                    Body = HttpService:JSONEncode({
                        success = true,
                        --
                        data = {
                            valid = true,
                        },
                    })
                }
            end
        end
	elseif Args[1].Url:find('webhookshandler') then
		return print('request(' .. Args[1].Url .. ')')
    end
    --
    return Original(table.unpack(Args))
end)

hookfunction(game.Shutdown, newcclosure(function()
	return print(':Shutdown()')
end))

